"""Exact post-diagnostic source union; never substitutes unqualified generated bytes."""
import hashlib
import json
from pathlib import Path
import subprocess

BASE = "rpc-union-20261123"
REPAIR = "schema-closure-repair-20261123"
BASE_SHA256 = "9386492e7687d44e9bcf31d5047957d341da77ff82c6ac7986b6ed976e764b2a"
REPAIR_SHA256 = "27b2b717cc8f959e3a33457dd60bb5f65fffcfefaa19d52d079c461571e97dea"
HEART = "d98420b1113536afd08cde6de9a5816f6d27ffff"
RPC_SOURCE = "5b4a29c7d3f0991d006321a6035a7f2f6757d3d0"
TARGET = "relation-target-closure-20261123"
TARGET_SHA256 = "b5174c36a8507df9c5fe2308565b529bdda5d06579c8ac0cd8bd1ec51630e81c"


def require(value, reason):
    if not value:
        raise RuntimeError(reason)


def identity(raw):
    return {"bytes": len(raw), "sha256": hashlib.sha256(raw).hexdigest(),
            "git_blob": hashlib.sha1(b"blob " + str(len(raw)).encode() + b"\0" + raw).hexdigest()}


def admit(*, control, packet_name, manifest, composition, read_bound, safe, git,
          original_repository=None, original_heart=None):
    def bound(relative, row):
        return read_bound(control, packet_name + "/" + relative, row)

    base_raw = bound(BASE + "/BASE_INPUTS.json", manifest["rpc_union_baseline"])
    repair_raw = bound(REPAIR + "/CLOSURE_REPAIR_INPUTS.json", manifest["schema_closure_repair"])
    require(identity(base_raw)["sha256"] == BASE_SHA256
            and identity(repair_raw)["sha256"] == REPAIR_SHA256,
            "Reviewed RPC baseline or source repair differs")
    base, repair = json.loads(base_raw), json.loads(repair_raw)
    require(base["source_commit"] == RPC_SOURCE and base["heart_base"] == HEART
            and base["baseline_native_rows"] == 88
            and base["activation_admitted"] is False
            and base["generated_qualification"] is None,
            "Frozen source-only baseline was retrospectively relabelled")
    require(repair["heart_base"] == HEART and repair["previous_native_run"] == 45251406927
            and repair["previous_control"] == "2f73090b0cf199fa778093f005db3cddff48c391"
            and repair["original_refusal_unchanged"] is True
            and repair["body_mapping_drain_assertions_unchanged"] is True
            and repair["original_semantic_leaves_required_fresh"] == 6
            and repair["original_native_leaves_required"] == 9
            and repair["new_control_leaf_count"] == 11,
            "Reviewed native scope or refusal contract differs")
    for key in ("diagnosis", "diff", "root_source_review"):
        bound(repair[key]["path"], repair[key])
    frozen = {row["path"]: row["sha256"]
              for row in composition["final_composed_changed_native_files"]}
    same = {row["path"]: row["sha256"] for row in base["native83_exact_unchanged_rows"]}
    deltas = base["seven_explicit_pre_generation_deltas"]
    require(len(same) == 81 and len(deltas) == 7
            and len({row["native_path"] for row in deltas}) == 7
            and same == {name: digest for name, digest in frozen.items()
                         if name not in {row["native_path"] for row in deltas}},
            "Original83/RPC88 baseline correspondence differs")
    overlays = []
    for row in deltas:
        after = bound(row["path"], row["after"])
        if row["base_kind"] == "native-frozen83":
            require(frozen.get(row["native_path"]) == row["base_sha256"],
                    "RPC overlay does not bind its frozen Native preimage")
        else:
            require(row["base_kind"] == "original-heart" and row["native_path"] not in frozen,
                    "RPC original-base overlay overlaps a composed Native path")
            require(row["original_heart"]["sha256"] == row["base_sha256"],
                    "RPC original-base identity differs")
        require(row["source_revision"] == RPC_SOURCE, "RPC baseline source revision differs")
        if original_repository is not None:
            require(after == git(original_repository, "show", RPC_SOURCE + ":" + row["source_path"]),
                    "RPC baseline bytes differ from their immutable source")
        if original_heart is not None and row["base_kind"] == "original-heart":
            if row["base_sha256"] is None:
                absent = subprocess.run(["git", "-C", str(original_heart), "cat-file", "-e",
                                         HEART + ":" + row["native_path"]],
                                        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=30)
                require(absent.returncode != 0, "RPC added file collides with original Heart")
            else:
                require(identity(git(original_heart, "show", HEART + ":" + row["native_path"]))
                        == row["original_heart"], "Original Heart RPC preimage differs")
        overlays.append({"layer": "reviewed-rpc-baseline", "native_path": row["native_path"],
                         "base_sha256": row["base_sha256"], "path": row["path"], **row["after"]})

    require(len(repair["inputs"]) == 4, "Native closure repair path count differs")
    for row in repair["inputs"]:
        after = bound(row["path"], row)
        if row["base_sha256"] is not None:
            before = safe(control, row["base_source_path"]).read_bytes()
            require(identity(before)["sha256"] == row["base_sha256"]
                    and before == git(control, "show", "HEAD:" + row["base_source_path"]),
                    "Reviewed closure-repair preimage differs")
            expected = before.decode()
            for change in row["changes"]:
                require(expected.count(change["before"]) == 1,
                        "Closure repair inverse is not unique")
                expected = expected.replace(change["before"], change["after"], 1)
            require(after == expected.encode(), "Closure repair escaped its reviewed inverse")
            if original_heart is not None and row.get("base_original_revision"):
                require(before == git(original_heart, "show", HEART + ":" + row["native_path"]),
                        "Reviewed exporter preimage differs from original Heart")
        elif original_heart is not None:
            absent = subprocess.run(["git", "-C", str(original_heart), "cat-file", "-e",
                                     HEART + ":" + row["native_path"]],
                                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=30)
            require(absent.returncode != 0, "Focused repair control collides with original Heart")
        overlays.append(dict(row, layer="reviewed-schema-closure-repair"))

    qualified_raw = bound(BASE + "/QUALIFIED_GENERATION.json", manifest["qualified_rpc_generation"])
    qualified = json.loads(qualified_raw)
    require(qualified["schema"] == 1
            and qualified["status"] == "AUTHENTIC_ORIGINAL_GENERATION_PASS_SWIFT_SEPARATE"
            and qualified["runtime_results_reused"] is False
            and qualified["native_tests_required_on_union"] == {"rpc": 9, "panic": 1},
            "New generated closure is not authentically qualified; no runtime reuse")
    retained_evidence = {}
    for row in qualified["evidence_inputs"]:
        raw = bound(row["path"], row)
        name = Path(row["path"]).name
        require(name not in retained_evidence, "Duplicated generator evidence name")
        retained_evidence[name] = raw
    producer = qualified["producer"]
    require(producer["run_id"] == 45261979047 and qualified["producer_run_attempt"] == 1
            and producer["head_sha"] == "af96f761efe2cb4d92f5296fec85a152fd3aef17"
            and producer["artifact_id"] == 14863070636 and producer["artifact_bytes"] == 58687556
            and producer["artifact_sha256"] == "1b8b5beda8e28322bc10ecebb37007b400aff2f17fa27c1e1dfc854f4c5eab2c"
            and qualified["aggregate_producer_result"] == "FAIL"
            and qualified["full_producer_or_mobile_abi_accepted"] is False,
            "Authentic partial generator qualification was relabelled")
    original_result = json.loads(retained_evidence["RESULT.json"])
    require(original_result["status"] == "FAIL" and original_result["control_head"] == producer["head_sha"]
            and original_result["error"] == "owned command failed: typecheck-changed-original-swift-primary-files"
            and original_result["native_source_tree"] == "995327648a4e4523c37208251ba54b47bccb2ab4"
            and original_result["owned_command_groups_drained"] is True,
            "Original generation/Swift terminal boundary differs")
    commands = json.loads(retained_evidence["COMMANDS.json"])
    commands = commands if isinstance(commands, list) else commands["commands"]
    labels = ("original-protoc-changed-go-commands", "original-proto-documentation",
              "original-protoc-changed-raw-swift", "original-protoc-changed-swift-models",
              "original-split-changed-commands", "original-generate-changed-error-localization")
    require(qualified["successful_generator_labels"] == list(labels),
            "Original generator command family differs")
    for label in labels:
        matches = [command for command in commands if command["label"] == label]
        require(len(matches) == 1, "Original generator command absent or duplicated")
        command = matches[0]
        require(command["status"] == "TERMINAL" and command["returncode"] == command["effective_returncode"] == 0
                and command["timed_out"] is False and command["start_new_session"] is True
                and any(row.get("drained") is True for row in command["cleanup"]),
                "Original generator did not succeed and drain")
        for stream in ("stdout", "stderr"):
            require(identity(retained_evidence[command[stream]])["sha256"] == command[stream + "_sha256"],
                    "Original generator command output binding differs")
    boundary = json.loads(retained_evidence["NATIVE_BOUNDARY_qualification-final.json"])
    require(boundary["changed_paths"] == boundary["outside_generated_outputs"] == boundary["rows"] == [],
            "Native generated source changed at the failure boundary")
    delta = json.loads(retained_evidence["CANCEL_ERROR_GENERATED_DELTA.json"])
    require({key: len(value) for key, value in delta["deltas"].items()} ==
            {"native": 2, "swift": 2, "middleware": 4},
            "Reviewed generated delta escaped its exact original family")
    generated_raw = bound(qualified["generated_index"]["path"], qualified["generated_index"])
    generated = json.loads(generated_raw)
    failure_outputs = json.loads(retained_evidence["FAILURE_OUTPUT_INDEX.json"])["roots"]
    require(failure_outputs["native"] == generated["native"]
            and {row["path"]: row for row in failure_outputs["swift"]} ==
                {row["path"]: row for row in generated["swift"] + generated["middleware"]}
            and sum(len(rows) for rows in generated.values()) == 744,
            "Actual generated outputs differ from final failure-time copies")
    rows = generated["native"]
    require(len(rows) == 11 and [row["path"] for row in rows] == sorted(row["path"] for row in rows)
            and len({row["path"] for row in rows}) == 11
            and sum(row["path"].endswith(".go") for row in rows) == 10
            and [row["path"] for row in rows if not row["path"].endswith(".go")] == ["docs/proto.md"],
            "Original generated11 output inventory differs")
    retained = qualified["native_generated_inputs"]
    require([row["native_path"] for row in retained] == [row["path"] for row in rows],
            "Retained generated outputs omit or substitute an original output")
    for row, original in zip(retained, rows):
        require({key: row[key] for key in ("bytes", "sha256", "git_blob")} ==
                {key: original[key] for key in ("bytes", "sha256", "git_blob")},
                "Retained generated output identity differs from authenticated index")
        bound(row["path"], row)
        if original_heart is not None:
            require(identity(git(original_heart, "show", HEART + ":" + row["native_path"]))
                    == row["original_heart"], "Generated output original preimage differs")
        require(row["base_sha256"] == row["original_heart"]["sha256"],
                "Generated original-base binding differs")

    schema = base["schema_append"]
    before = bound(next(row["path"] for row in deltas
                        if row["native_path"] == schema["native_path"]), schema["before"])
    require(before.decode().count(schema["before_fragment"]) == 1,
            "Original Cancel enum source fragment is not unique")
    after = before.decode().replace(schema["before_fragment"], schema["after_fragment"], 1).encode()
    expected_schema = {key: schema["after"][key] for key in ("bytes", "sha256", "git_blob")}
    require(identity(after) == expected_schema and
            schema["wire_values"] == {"NULL": 0, "BAD_INPUT": 1, "RUNTIME_UNAVAILABLE": 2, "UNKNOWN_ERROR": 3},
            "Append-only Cancel enum differs")
    schema_row = qualified["schema_afterimage"]
    require(schema_row["native_path"] == schema["native_path"] and
            {key: schema_row[key] for key in expected_schema} == expected_schema
            and bound(schema_row["path"], schema_row) == after,
            "Qualified Cancel schema is not the exact original append")
    overlays.append(dict(schema_row, layer="qualified-cancel-schema",
                         base_sha256=schema["before"]["sha256"]))
    overlays += [dict(row, layer="qualified-original-generated-output") for row in retained]

    tests = base["rpc_test_inputs"]
    require(len(tests) == 4 and sum(len(row["test_names"]) for row in tests) == 10,
            "Original RPC9/panic control inventory differs")
    for row in tests:
        after = bound(row["path"], row)
        if original_repository is not None:
            require(after == git(original_repository, "show", row["source_revision"] + ":" + row["source_path"]),
                    "RPC control differs from its immutable source")
        overlays.append(dict(row, layer="original-rpc-control", base_sha256=None))
    for key in ("rpc_helper", "rpc_control_spec"):
        row = qualified[key]
        raw = bound(row["path"], row)
        require(row["source_revision"] == "dfb28b4fee8ff36d16ebe435ba648ad664312c12",
                "Reviewed callable RPC helper revision differs")
        if original_repository is not None:
            require(raw == git(original_repository, "show", row["source_revision"] + ":" + row["source_path"]),
                    "Callable RPC control bytes differ from immutable reviewed source")
    target = admit_relation_target(
        control=control, packet_name=packet_name, manifest=manifest, bound=bound, safe=safe, git=git,
        original_repository=original_repository, original_heart=original_heart)
    overlays += [dict(row, layer="reviewed-relation-target-type-closure") for row in target["inputs"]]
    return {"baseline": base, "repair": repair, "qualified": qualified, "overlays": overlays,
            "relation_target": target,
            "generated_index": generated, "generated_index_path": qualified["generated_index"]["path"]}


def admit_relation_target(*, control, packet_name, manifest, bound, safe, git,
                          original_repository=None, original_heart=None):
    raw = bound(TARGET + "/TARGET_CLOSURE_INPUTS.json", manifest["relation_target_closure"])
    require(identity(raw)["sha256"] == TARGET_SHA256, "Reviewed relation-target overlay differs")
    repair = json.loads(raw)
    require(repair["schema"] == 1 and repair["heart_base"] == HEART
            and repair["previous_control"] == "c6b4ebd03d25433b8a47073d84e2efa874c777ec"
            and repair["previous_native_run"] == 45270881714 and repair["previous_run_attempt"] == 1
            and repair["previous_native_tree"] == "b89202220ac75600f69825d50ec313c1d66cf2fd"
            and repair["previous_aggregate_result"] == "FAIL"
            and repair["original_refusal_unchanged"] is True
            and repair["schema_comparator_unchanged"] is True
            and repair["body_mapping_drain_assertions_unchanged"] is True
            and repair["fixed_type_names_or_cids"] is False
            and repair["runtime_results_reused"] is False
            and repair["production_import_activated"] is False
            and repair["new_control_leaf_count"] == 12
            and repair["fresh_control_counts"] == manifest["fresh_control_counts"] ==
                {"native": 9, "schema_repair": 11, "relation_target": 12, "semantic": 6, "rpc": 9, "panic": 1},
            "Relation-target repair changed original scope, refusal or fresh execution requirements")
    for key in ("diff", "source_rows", "diagnosis", "root_source_review", "control_helper"):
        bound(repair[key]["path"], repair[key])
    proof = {}
    for row in repair["previous_evidence"]:
        name = Path(row["path"]).name
        require(name not in proof, "Duplicate retained original failure evidence")
        proof[name] = (row, json.loads(bound(row["path"], row)))
    require(set(proof) == {"AUTHENTICATED_INTAKE.json", "RESULT.json",
                          "text-schema-comparison-diagnostic.json"},
            "Retained original failure evidence inventory differs")
    intake = proof["AUTHENTICATED_INTAKE.json"][1]
    previous = proof["RESULT.json"][1]
    require(intake["run"] == repair["previous_native_run"] and intake["attempt"] == 1
            and intake["source"] == repair["previous_control"] and intake["aggregate_conclusion"] == "failure"
            and intake["archive"]["sha256"] == repair["previous_artifact"]["sha256"]
            and intake["archive"]["bytes"] == repair["previous_artifact"]["bytes"]
            and intake["artifact"]["id"] == repair["previous_artifact"]["id"]
            and intake["crc_members_verified"] == 215 and intake["index_rows_verified"] == 214
            and previous["control_head"] == repair["previous_control"] and previous["status"] == "FAIL"
            and previous["fixture_evidence"] == "NOT_REACHED"
            and {key: previous["native_cases"][key] for key in repair["previous_native_counts"]} ==
                repair["previous_native_counts"] ==
                {"leaf_pass": 0, "leaf_fail": 1, "leaf_skip": 0, "leaf_not_run": 8}
            and previous["post_execution_source_module_link_stability"]["status"] == "PASS"
            and previous["owned_command_groups_drained"] is True,
            "Original failed union boundary was changed or relabelled")
    indexed = {row["path"]: row for row in intake["verified_rows"]}
    for name, archive_name in (
        ("RESULT.json", "RESULT.json"),
        ("text-schema-comparison-diagnostic.json",
         "fixtures/target-text/text-schema-comparison-diagnostic.json"),
    ):
        row = proof[name][0]
        require({key: indexed[archive_name][key] for key in ("bytes", "sha256")} ==
                {key: row[key] for key in ("bytes", "sha256")},
                "Retained original failure body differs from authenticated artifact index")
    inputs = repair["inputs"]
    require(len(inputs) == 2 and {row["native_path"] for row in inputs} == {
        "core/block/export/collection.go",
        "core/block/export/owned_annotation_relation_target_closure_test.go"},
        "Relation-target overlay escaped its two reviewed paths")
    for row in inputs:
        after = bound(row["path"], row)
        require(row["path"] == TARGET + "/native/" + row["native_path"],
                "Relation-target retained path does not match its actual native source")
        if row["base_sha256"] is not None:
            before = bound(row["retained_preimage"]["path"], row["retained_preimage"])
            require(identity(before)["sha256"] == row["base_sha256"]
                    and before == safe(control, row["base_source_path"]).read_bytes()
                    and before == git(control, "show", "HEAD:" + row["base_source_path"])
                    and indexed["qualified-native-source/" + row["native_path"]]["sha256"] ==
                        row["base_sha256"],
                    "Relation-target repair does not bind the actual previous union preimage")
            if original_repository is not None:
                require(before == git(original_repository, "show",
                                      repair["previous_control"] + ":" + row["base_source_path"]),
                        "Relation-target preimage differs from immutable failed source")
            expected = before.decode()
            require(len(row["changes"]) == 3, "Relation-target inverse count differs")
            for change in row["changes"]:
                require(expected.count(change["before"]) == 1, "Relation-target inverse is not unique")
                expected = expected.replace(change["before"], change["after"], 1)
            require(after == expected.encode(), "Relation-target repair escaped its reviewed inverse")
        else:
            require(row["native_path"].endswith("_test.go") and row["changes"] == [],
                    "Only the reviewed new test may have an absent preimage")
            if original_heart is not None:
                absent = subprocess.run(["git", "-C", str(original_heart), "cat-file", "-e",
                                         HEART + ":" + row["native_path"]],
                                        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=30)
                require(absent.returncode != 0, "Relation-target control collides with original Heart")
    return repair


def expected_union(union, prior_afterimages, prior_required):
    final, required = dict(prior_afterimages), dict(prior_required)
    for row in union["overlays"]:
        name = row["native_path"]
        if name in final:
            require(final[name] == row["base_sha256"], "Union layer has a wrong preceding afterimage: " + name)
        final[name] = row["sha256"]
        if name.endswith(".go"):
            required[name] = row["sha256"]
    return final, required


def apply(*, union, control, packet_name, heart, composed, read_bound, safe):
    for row in union["overlays"]:
        name = row["native_path"]
        path = safe(heart, name)
        before = row["base_sha256"]
        require((path.is_file() and not path.is_symlink()
                 and identity(path.read_bytes())["sha256"] == before)
                if before is not None else not path.exists(),
                "Union preimage differs: " + name)
        after = read_bound(control, packet_name + "/" + row["path"], row)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(after)
        require(identity(path.read_bytes()) ==
                {key: row[key] for key in ("bytes", "sha256", "git_blob")},
                "Union materialized afterimage differs: " + name)
        composed[name] = row["sha256"]
    return composed
